-- =====================================================
-- PHASE 37: Shopper IDs + admin-managed registration (2026-10-28)
--   * shoppers.shopper_code: permanent public Shopper ID, GET-SHP-000001
--     style, generated by the database for every new shopper (app or
--     admin registration), unique, and never changed (trigger). The
--     internal id and all relationships stay as they are.
--   * admin registration reuses the shopper application (same fields,
--     documents, vehicle photos, per-document review, approval);
--     channel + registering admin recorded
--   * an admin-registered account has no password until the shopper
--     activates it with a one-time code (owner's choice: shown once to
--     the registering admin to hand over in person, SMS too once
--     Notify.lk is configured); codes stored as hashes, single use,
--     72 h
-- =====================================================

BEGIN;

CREATE SEQUENCE IF NOT EXISTS shopper_code_seq START 1;

CREATE OR REPLACE FUNCTION next_shopper_code() RETURNS TEXT AS $$
DECLARE
  n BIGINT := nextval('shopper_code_seq');
BEGIN
  -- 6 digits, growing past 999999 instead of wrapping
  RETURN 'GET-SHP-' || CASE WHEN n < 1000000 THEN lpad(n::text, 6, '0') ELSE n::text END;
END;
$$ LANGUAGE plpgsql;

ALTER TABLE shoppers ADD COLUMN IF NOT EXISTS shopper_code VARCHAR(20);

-- Existing shoppers, in the order they joined
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN SELECT id FROM shoppers WHERE shopper_code IS NULL ORDER BY created_at, id LOOP
    UPDATE shoppers SET shopper_code = next_shopper_code() WHERE id = r.id;
  END LOOP;
END $$;

ALTER TABLE shoppers ALTER COLUMN shopper_code SET DEFAULT next_shopper_code();
ALTER TABLE shoppers ALTER COLUMN shopper_code SET NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS shoppers_shopper_code_key ON shoppers (shopper_code);

-- Permanent: refuse any change of a Shopper ID
CREATE OR REPLACE FUNCTION keep_shopper_code() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.shopper_code IS DISTINCT FROM OLD.shopper_code THEN
    RAISE EXCEPTION 'Shopper ID % can not be changed', OLD.shopper_code USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS shoppers_keep_code ON shoppers;
CREATE TRIGGER shoppers_keep_code BEFORE UPDATE OF shopper_code ON shoppers
  FOR EACH ROW EXECUTE FUNCTION keep_shopper_code();

-- Registration channel + activation
ALTER TABLE shoppers
  ADD COLUMN IF NOT EXISTS registration_channel VARCHAR(10) NOT NULL DEFAULT 'app',
  ADD COLUMN IF NOT EXISTS registered_by_admin INTEGER REFERENCES admins(id) ON DELETE SET NULL,
  -- NULL = an admin-registered account not activated yet (can't sign in)
  ADD COLUMN IF NOT EXISTS activated_at TIMESTAMPTZ DEFAULT NOW();

ALTER TABLE shoppers DROP CONSTRAINT IF EXISTS shoppers_registration_channel_check;
ALTER TABLE shoppers
  ADD CONSTRAINT shoppers_registration_channel_check CHECK (registration_channel IN ('app', 'admin'));

-- Accounts from before this phase signed up themselves: active
UPDATE shoppers SET activated_at = created_at WHERE activated_at IS NULL AND registration_channel = 'app';

ALTER TABLE shopper_applications
  ADD COLUMN IF NOT EXISTS created_by_admin INTEGER REFERENCES admins(id) ON DELETE SET NULL,
  -- Terms / privacy accepted on paper or in person, recorded by an admin
  ADD COLUMN IF NOT EXISTS consent_recorded_by INTEGER REFERENCES admins(id) ON DELETE SET NULL;

CREATE TABLE IF NOT EXISTS shopper_activation_codes (
  id SERIAL PRIMARY KEY,
  shopper_id INTEGER NOT NULL REFERENCES shoppers(id) ON DELETE CASCADE,
  code_hash VARCHAR(64) NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  used_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ,
  sent_by_sms BOOLEAN NOT NULL DEFAULT FALSE,
  created_by INTEGER REFERENCES admins(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS shopper_activation_codes_shopper_idx
  ON shopper_activation_codes (shopper_id, created_at DESC);

COMMIT;
